const aiData = $input.first().json;
const driveData = $('8. Build Direct Link').first().json;

let caption = '';

// Parse Gemini API Response Format
if (aiData && aiData.candidates && aiData.candidates[0] && aiData.candidates[0].content && aiData.candidates[0].content.parts && aiData.candidates[0].content.parts[0]) {
  caption = aiData.candidates[0].content.parts[0].text;
}
// Fallback to OpenAI format just in case
else if (aiData && aiData.choices && aiData.choices[0] && aiData.choices[0].message && typeof aiData.choices[0].message.content === 'string') {
  caption = aiData.choices[0].message.content;
}
else if (typeof aiData === 'string') caption = aiData;

// Cleanup: turn literal '\n' text into real line breaks, remove ** markdown bold markers
caption = (caption || '').replace(/\\n/g, '\n').replace(/\*\*/g, '').trim();

// Safety fallback
if (!caption || caption.toLowerCase().includes('not found')) {
  caption = 'Auto-posted from Telegram via Google Drive';
}

return [{
  json: {
    ...driveData,
    ai_caption: caption
  }
}];
